function chooser(){let others=S.docs.filter(d=>d.id!==S.selected);app.innerHTML='<section class="chooser"><div class="chooser-head"><button class="back-button"><img class="icon" src="'+ICON+'chevron-left.svg" alt="">戻る</button><h2>ほかの文書（'+others.length+'）</h2></div><div class="card-grid"></div></section>';$('.back-button').onclick=()=>{S.chooser=false;render();requestAnimationFrame(()=>S.docTrigger?.focus())};let g=$('.card-grid');others.forEach(d=>{let b=document.createElement('button');b.className='card';b.ariaLabel=d.label+' '+d.affiliation;b.innerHTML='<span class="thumbnail" aria-hidden="true"><i></i><i></i><i></i></span><span><strong></strong><span class="aff"></span></span>';b.querySelector('strong').textContent=d.label;b.querySelector('.aff').textContent=d.affiliation;b.onclick=()=>{S.selected=d.id;S.chooser=false;render();requestAnimationFrame(()=>$('#docrow .tab[aria-selected=true]')?.focus())};g.append(b)})}
function toggleItems(b,vals,sel){S.itemTrigger=b;S.itemOpen=!S.itemOpen;render();requestAnimationFrame(()=>S.itemOpen?$('.item-option')?.focus():$('#itemrow .count-button')?.focus())}
function popover(host,vals,sel){let p=document.createElement('div');p.className='item-popover';vals.filter(v=>v.id!==sel.id).forEach(v=>{let b=document.createElement('button');b.className='item-option';b.textContent=v.label;b.onclick=()=>{S.items.set(S.selected,current().items[+v.id]);S.itemOpen=false;render();requestAnimationFrame(()=>$('#itemrow .count-button')?.focus())};p.append(b)});host.append(p)}
